//! IDE documents are generated by Core, independently of either frontend.
use crate::{
    operations::{configure_values, make_plan, pending, Lock},
    workspace::*,
};
use serde_json::{json, Value};
use std::{
    fs,
    path::{Path, PathBuf},
};

fn xml(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\n', "&#10;")
        .replace('\r', "&#13;")
}
fn quoted(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}
fn bracket(s: &str) -> String {
    let mut eq = String::new();
    while s.contains(&format!("]{eq}]")) {
        eq.push('=');
    }
    format!("[{eq}[{s}]{eq}]")
}
fn write(path: &Path, text: &str, seed: bool) -> Result<()> {
    if seed && path.exists() {
        return Ok(());
    }
    if fs::read_to_string(path).ok().as_deref() == Some(text) {
        return Ok(());
    }
    fs::create_dir_all(path.parent().ok_or("Missing IDE directory")?).map_err(|e| e.to_string())?;
    let temp = path.with_extension(format!("{}.tmp", std::process::id()));
    fs::write(&temp, text).map_err(|e| e.to_string())?;
    fs::rename(temp, path).map_err(|e| e.to_string())
}
fn clangd(profile: &Profile, c: &std::collections::BTreeMap<String, String>) -> Option<PathBuf> {
    c.get("CMAKE_CXX_COMPILER")
        .or(c.get("CMAKE_C_COMPILER"))
        .and_then(|s| Path::new(s).parent())
        .map(|p| p.join("clangd"))
        .filter(|p| p.is_file())
        .or_else(|| {
            Path::new(&profile.cxx)
                .parent()
                .map(|p| p.join("clangd"))
                .filter(|p| p.is_file())
        })
        .or_else(|| tool_path("clangd"))
        .or_else(|| {
            [
                "/opt/homebrew/opt/llvm/bin/clangd",
                "/usr/local/opt/llvm/bin/clangd",
            ]
            .iter()
            .map(PathBuf::from)
            .find(|p| p.is_file())
        })
}
fn merge_named(items: &mut Value, new: Value, key: &str) -> Result<()> {
    let a = items
        .as_array_mut()
        .ok_or("Invalid IDE document array. Restore its JSON structure before exporting again.")?;
    if let Some(i) = a.iter().position(|v| v[key] == new[key]) {
        a[i] = new;
    } else {
        a.push(new);
    }
    Ok(())
}

pub(crate) fn definition_matches(key: &str, wanted: &str, actual: Option<&String>) -> bool {
    if actual.map(String::as_str) == Some(wanted) {
        return true;
    }
    if key != "CMAKE_PROJECT_INCLUDE_BEFORE" {
        return false;
    }
    let Some(path) = actual.map(Path::new) else {
        return false;
    };
    if !path.starts_with(data_home().join("ide"))
        || path.file_name().and_then(|s| s.to_str()) != Some("reload.cmake")
    {
        return false;
    }
    path.parent()
        .and_then(|p| read_json(&p.join("upstream-includes.json")).ok())
        .and_then(|v| serde_json::from_value::<Vec<String>>(v).ok())
        .is_some_and(|v| v.join(";") == wanted)
}

pub(crate) fn export(root: &Path, p: &Profile, request: &Value) -> Result<Value> {
    let ide = request["ide"].as_str().unwrap_or("");
    if !["clion", "vscode"].contains(&ide) {
        return Err("Choose CLion or VS Code.".into());
    }
    let _guard = Lock::acquire(&p.build_dir)?;
    let c = check_source(root, p)?;
    if pending(p) {
        return Err("Settings changed. Prepare the environment before opening an IDE.".into());
    }
    let build = Path::new(&p.build_dir);
    if !build.join("compile_commands.json").exists() {
        return Err(
            "Compilation database is missing. Prepare the environment before opening an IDE."
                .into(),
        );
    }
    let all = artifacts(build)?;
    let target_name = request["target"].as_str().unwrap_or("");
    let target = if target_name.is_empty() {
        None
    } else {
        Some(
            all.iter()
                .find(|a| a.name == target_name)
                .ok_or("The selected IDE target is unavailable. Refresh the environment.")?,
        )
    };
    let arguments: Vec<String> =
        serde_json::from_value(request.get("arguments").cloned().unwrap_or(json!([])))
            .map_err(|_| "IDE arguments must be a list of strings.")?;
    let home = data_home()
        .join("ide")
        .join(workspace_key(root))
        .join(hash(&p.id));
    let values = configure_values(p)?;
    let configure = make_plan(root, p, &json!({"operation":"configure"}))?
        .steps
        .remove(0);
    let executable = target.filter(|a| a.kind == "EXECUTABLE" && !a.paths.is_empty());
    let mut extensions = vec![];
    let path;
    let clangd = clangd(p, &c);
    if ide == "clion" {
        path = home.join("clion");
        let idea = path.join(".idea");
        let settings = path.join("environment.cmake");
        let reload = path.join("reload.cmake");
        // -C cache scripts are not CMake inputs. CLion otherwise keeps its old
        // target model when this file changes while the project is open.
        // The hook only registers dependencies; it must never apply old IDE
        // options during a later Workbench configure.
        let hook_key = "CMAKE_PROJECT_INCLUDE_BEFORE";
        let hooks_file = path.join("upstream-includes.json");
        let current = values.get(hook_key).or_else(|| c.get(hook_key));
        let hooks: Vec<String> = if current.is_some_and(|v| v == reload.to_string_lossy().as_ref())
        {
            if hooks_file.exists() {
                serde_json::from_value(read_json(&hooks_file)?).map_err(|e| e.to_string())?
            } else {
                vec![]
            }
        } else {
            current
                .into_iter()
                .flat_map(|v| v.split(';'))
                .filter(|v| !v.is_empty())
                .map(str::to_owned)
                .collect()
        };
        let mut hook = String::from(
            "# Generated by LLVM Workbench. Registers IDE settings as CMake inputs.\n",
        );
        for include in &hooks {
            hook.push_str(&format!("include({})\n", bracket(include)));
        }
        hook.push_str(&format!(
            "set_property(DIRECTORY APPEND PROPERTY CMAKE_CONFIGURE_DEPENDS {})\n",
            bracket(&settings.to_string_lossy())
        ));
        write_json(&hooks_file, &hooks)?;
        let mut preload = String::from(
            "# Generated by LLVM Workbench. Edit environment settings in Workbench.\n",
        );
        for (k, v) in &values {
            preload.push_str(&format!(
                "set({} {} CACHE STRING \"LLVM Workbench\" FORCE)\n",
                bracket(k),
                bracket(v)
            ));
        }
        preload.push_str(&format!(
            "set({hook_key} {} CACHE FILEPATH \"LLVM Workbench CMake input tracking\" FORCE)\n",
            bracket(&reload.to_string_lossy())
        ));
        // The cache's resolved compilers also cover environments that selected system defaults.
        for k in ["CMAKE_C_COMPILER", "CMAKE_CXX_COMPILER"] {
            if !values.contains_key(k) {
                if let Some(v) = c.get(k) {
                    preload.push_str(&format!(
                        "set({k} {} CACHE FILEPATH \"LLVM Workbench\" FORCE)\n",
                        bracket(v)
                    ));
                }
            }
        }
        write(&settings, &preload, false)?;
        // Publish the hook last: a watcher must not reload before the matching
        // settings have been written.
        write(&reload, &hook, false)?;
        write(&idea.join(".name"), &format!("LLVM · {}", p.name), false)?;
        write(&idea.join("misc.xml"), &format!("<project version=\"4\"><component name=\"CMakeWorkspace\" PROJECT_DIR=\"{}\"><contentRoot DIR=\"{}\" /></component></project>\n",xml(&root.join("llvm").to_string_lossy()),xml(&root.to_string_lossy())),true)?;
        let options = format!("-G Ninja -C {}", quoted(&settings.to_string_lossy()));
        write(&idea.join("workspace.xml"), &format!("<project version=\"4\"><component name=\"CMakeSettings\"><configurations><configuration PROFILE_NAME=\"Workbench\" ENABLED=\"true\" CONFIG_NAME=\"{}\" GENERATION_DIR=\"{}\" GENERATION_OPTIONS=\"{}\" BUILD_OPTIONS=\"-j {}\" /></configurations></component></project>\n",p.build_type(),xml(&p.build_dir),xml(&options),p.jobs),true)?;
        if let Some(a) = executable {
            let project = c
                .get("CMAKE_PROJECT_NAME")
                .map(String::as_str)
                .unwrap_or("LLVM");
            let params = arguments
                .iter()
                .map(|a| quoted(a))
                .collect::<Vec<_>>()
                .join(" ");
            // Seed once: IDE edits to arguments, environment variables and breakpoints survive reopening.
            write(&idea.join("runConfigurations").join(format!("workbench-{}.xml",hash(&a.name))), &format!("<component name=\"ProjectRunConfigurationManager\"><configuration default=\"false\" name=\"Workbench: {}\" type=\"CMakeRunConfiguration\" factoryName=\"Application\" REDIRECT_INPUT=\"false\" ELEVATE=\"false\" USE_EXTERNAL_CONSOLE=\"false\" EMULATE_TERMINAL=\"false\" WORKING_DIR=\"file://{}\" PASS_PARENT_ENVS_2=\"true\" PROJECT_NAME=\"{}\" TARGET_NAME=\"{}\" CONFIG_NAME=\"Workbench\" RUN_PATH=\"{}\" PROGRAM_PARAMS=\"{}\"><method v=\"2\"><option name=\"com.jetbrains.cidr.execution.CidrBuildBeforeRunTaskProvider$BuildBeforeRunTask\" enabled=\"true\" /></method></configuration></component>\n",xml(&a.name),xml(&root.to_string_lossy()),xml(project),xml(&a.name),xml(&a.paths[0]),xml(&params)),true)?;
        }
    } else {
        let clangd = clangd
            .as_ref()
            .ok_or("clangd was not found. Install LLVM with clangd before opening VS Code.")?;
        path = home.join("LLVM Workbench.code-workspace");
        let mut doc = if path.exists() {
            read_json(&path).map_err(|_|"The generated VS Code workspace contains invalid JSON or comments. Save it as valid JSON before exporting again; your file has not been changed.")?
        } else {
            json!({"folders":[{"name":"LLVM","path":root}],"settings":{},"tasks":{"version":"2.0.0","tasks":[],"inputs":[]},"launch":{"version":"0.2.0","configurations":[]},"extensions":{"recommendations":[]}})
        };
        let settings = doc["settings"]
            .as_object_mut()
            .ok_or("Invalid VS Code settings object.")?;
        let mut flags = vec![
            format!("--compile-commands-dir={}", p.build_dir),
            "--background-index".into(),
        ];
        let drivers: Vec<_> = ["CMAKE_C_COMPILER", "CMAKE_CXX_COMPILER"]
            .iter()
            .filter_map(|k| c.get(*k))
            .cloned()
            .collect();
        if !drivers.is_empty() {
            flags.push(format!("--query-driver={}", drivers.join(",")));
        }
        for (k, v) in [
            ("clangd.path", json!(clangd)),
            ("clangd.arguments", json!(flags)),
            ("C_Cpp.intelliSenseEngine", json!("disabled")),
            ("cmake.configureOnOpen", json!(false)),
            ("cmake.useCMakePresets", json!("never")),
            (
                "window.title",
                json!(format!(
                    "${{activeEditorShort}}${{separator}}LLVM · {}${{separator}}${{appName}}",
                    p.name
                )),
            ),
            ("cmake.sourceDirectory", json!(root.join("llvm"))),
            ("cmake.buildDirectory", json!(p.build_dir)),
            ("cmake.generator", json!("Ninja")),
            ("cmake.configureSettings", json!(values)),
        ] {
            settings.insert(k.into(), v);
        }
        for key in ["files.watcherExclude", "search.exclude"] {
            let object = settings
                .entry(key.to_string())
                .or_insert(json!({}))
                .as_object_mut()
                .ok_or("Invalid VS Code exclusion settings.")?;
            object.insert("**/build/**".into(), json!(true));
        }
        let env_path = std::env::var("PATH").unwrap_or_default();
        let options = json!({"cwd":root,"env":{"PATH":format!("{env_path}:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin")}});
        let config_task = json!({"label":"Workbench: prepare environment","type":"process","command":configure.program,"args":configure.args,"options":options,"problemMatcher":[]});
        merge_named(&mut doc["tasks"]["tasks"], config_task, "label")?;
        let mut build_args = vec![
            "--build".to_string(),
            p.build_dir.clone(),
            "--parallel".into(),
            p.jobs.to_string(),
            "--target".into(),
        ];
        build_args.push("${input:workbenchTarget}".into());
        merge_named(
            &mut doc["tasks"]["inputs"],
            json!({"id":"workbenchTarget","type":"pickString","description":"Build target","options":all.iter().map(|a|&a.name).collect::<Vec<_>>(),"default":target.map(|a|a.name.as_str()).or_else(||all.first().map(|a|a.name.as_str())).unwrap_or("")}),
            "id",
        )?;
        merge_named(
            &mut doc["tasks"]["tasks"],
            json!({"label":"Workbench: choose build target","type":"process","command":configure.program,"args":build_args,"options":options,"problemMatcher":["$gcc"]}),
            "label",
        )?;
        if let Some(t) = target {
            build_args.pop();
            build_args.push(t.name.clone());
            let label = format!("Workbench: build {}", t.name);
            // Exactly one default build task, even after exporting another selected target.
            if let Some(tasks) = doc["tasks"]["tasks"].as_array_mut() {
                for task in tasks {
                    if task["label"]
                        .as_str()
                        .unwrap_or("")
                        .starts_with("Workbench: build ")
                    {
                        task["group"] = json!("build");
                    }
                }
            }
            merge_named(
                &mut doc["tasks"]["tasks"],
                json!({"label":label,"type":"process","command":configure.program,"args":build_args,"options":options,"group":{"kind":"build","isDefault":true},"problemMatcher":["$gcc"]}),
                "label",
            )?;
            if let Some(a) = executable {
                let name = format!("Workbench: {}", a.name);
                // Preserve IDE-authored arguments on subsequent opens.
                if !doc["launch"]["configurations"]
                    .as_array()
                    .ok_or("Invalid VS Code launch configurations.")?
                    .iter()
                    .any(|v| v["name"] == name)
                {
                    merge_named(
                        &mut doc["launch"]["configurations"],
                        json!({"name":name,"type":"lldb","request":"launch","program":a.paths[0],"args":arguments,"cwd":root,"preLaunchTask":label}),
                        "name",
                    )?;
                }
            }
        }
        for (id, name) in [
            ("llvm-vs-code-extensions.vscode-clangd", "clangd"),
            ("vadimcn.vscode-lldb", "CodeLLDB"),
        ] {
            let recommendations = doc["extensions"]["recommendations"]
                .as_array_mut()
                .ok_or("Invalid VS Code extension recommendations.")?;
            if !recommendations.contains(&json!(id)) {
                recommendations.push(json!(id));
            }
            extensions.push(json!({"id":id,"name":name}));
        }
        // A recoverable copy also preserves any user-authored fields if a future schema changes.
        if path.exists() {
            let old = fs::read(&path).map_err(|e| e.to_string())?;
            if old != serde_json::to_vec_pretty(&doc).map_err(|e| e.to_string())? {
                fs::write(path.with_extension("code-workspace.previous"), old)
                    .map_err(|e| e.to_string())?;
            }
        }
        write_json(&path, &doc)?;
    }
    Ok(
        json!({"ide":ide,"path":path,"build_dir":p.build_dir,"target":target_name,"extensions":extensions,"clangd":clangd,"debug_symbols":p.mode!="release"}),
    )
}
